INSERT INTO menu_items (id, category_id, name_en, name_kr, name_kr_subtitle, name_jp, name_vi, description_en, description_kr, description_vi, description_jp, portion_en, portion_vi, portion_kr, portion_jp, base_price, prep_time_minutes, image_url, image_public_id, alt_text, is_best_seller, is_chef_signature, is_limited, is_spicy, spice_level, spice_note, active, display_order, created_at, updated_at) VALUES ('spring-signature-set', 'japanese', 'SPRING SIGNATURE SET', '봄 시그니처 세트.', NULL, 'スプリングシグネチャーセット', NULL, 'A special set recommended for those looking to make today''s meal a little more special. Featuring 2 pieces of tender and juicy Special Tenderloin Katsu, 2 pieces of Cheese Katsu, 2 pieces of Shiitake Menchi Katsu packed with the rich flavor of shiitake mushrooms, and 1 crispy King Tiger Shrimp. Enjoy a variety of Spring''s signature flavors, all in one set.', '특별한 오늘의 한끼를 원하시는 분께 추천드리는 세트입니다. 부드럽고 육즙 가득한 특안심카츠 2조각, 치즈카츠 2조각, 버섯의 깊은 풍미를 살린 표고멘치카츠 2조각, 그리고 바삭하게 튀겨낸 킹타이거 새우 1마리로 구성했습니다. 봄돈까스의 다채로운 맛을 즐기실 수 있습니다.', 'Một Set đặc biệt hơn bình thường tại Cutlet Spring. Set gồm 2 miếng thăn nội cao cấp mềm mọng nước, 2 miếng Cheese Katsu, 2 miếng Shiitake Menchi Katsu đậm đà hương vị nấm hương, cùng 1 tôm sú King Tiger cỡ lớn chiên giòn.', '本日の食事をちょっと特別なものにしたい方におすすめの、SPRING自慢のスペシャルセットです。ジューシーで柔らかなスペシャルヒレカツ2個、とろりと濃厚なチーズを包んだチーズカツ2個、しいたけの豊かな旨味を存分に楽しめるしいたけメンチカツ2個、そしてサクサクに揚げたキングタイガーエビフライ1尾を贅沢に盛り合わせました。SPRING自慢のさまざまな味わいを、一度にお楽しみいただけるスペシャルセットです。', 'Set for 1 person', 'Set dành cho 1 người', '1인 세트', '1名様用セット', 275, 20, NULL, NULL, 'Spring Signature Set Tonkatsu with King Tiger Prawn, Cheese Katsu, Shiitake Menchi', false, true, false, false, 0, NULL, TRUE, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
