INSERT INTO menu_items (id, category_id, name_en, name_kr, name_kr_subtitle, name_jp, name_vi, description_en, description_kr, description_vi, description_jp, portion_en, portion_vi, portion_kr, portion_jp, base_price, prep_time_minutes, image_url, image_public_id, alt_text, is_best_seller, is_chef_signature, is_limited, is_spicy, spice_level, spice_note, active, display_order, created_at, updated_at) VALUES ('double-tender-duo-set', 'japanese', 'Double Tender Set', '더블 텐더 세트', '(Chicken & Pork)', 'ダブルテンダーセット', 'Set Tonkatsu Gà + Heo', 'Half pork tenderloin and half chicken tenderloin - soft, juicy, and perfectly crispy. Served with Tonkatsu and Tartar sauces.', '돼지 안심과 닭 안심을 반반 담아 부드럽고 촉촉하게 튀겨냈습니다. 돈카스 소스와 타르타르 소스를 함께 제공합니다.', 'Một nửa thịt thăn heo và một nửa thịt thăn gà - mềm, mọng nước và chiên giòn hoàn hảo. Dùng kèm hai loại sốt: Tonkatsu và Tartar.', '豚ヒレと鶏ささみを半分ずつ楽しめるセット。柔らかくジューシーに揚げ、とんかつソースとタルタルソースを添えました。', NULL, NULL, NULL, NULL, 200, 15, NULL, NULL, 'Double tender chicken and pork cutlet combination', false, false, false, false, 0, NULL, TRUE, 7, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
