INSERT INTO menu_items (id, category_id, name_en, name_kr, name_kr_subtitle, name_jp, name_vi, description_en, description_kr, description_vi, description_jp, portion_en, portion_vi, portion_kr, portion_jp, base_price, prep_time_minutes, image_url, image_public_id, alt_text, is_best_seller, is_chef_signature, is_limited, is_spicy, spice_level, spice_note, active, display_order, created_at, updated_at) VALUES ('korean-style-retro-tonkatsu', 'korean', 'Korean-style Tonkatsu', '경양식 돈까스', NULL, '韓国式とんかつ', 'Tonkatsu Kiểu Hàn', 'Tenderized pork loin cutlet served crispy with a rich, classic brown sauce. We can serve the sauce separately.', '두툼한 등심돈까스에 브라운소스가 함께 제공됩니다. (소스 따로 가능)', 'Thịt thăn heo được đập mềm, chiên giòn vàng và dùng kèm nước sốt nâu đậm đà kiểu cổ điển. Sốt có thể để riêng.', '豚ロース肉をやわらかく叩いてから、サクサクに揚げ、昔ながらの濃厚なブラウンソースとともにお召し上がりいただく一品です。ソースは別添えにできます。', NULL, NULL, NULL, NULL, 150, 15, '/images/menu/korean/korean-style-tonkatsu.jpg', NULL, 'Korean retro-style pounded pork cutlet served with rich brown sauce', false, false, false, false, 0, NULL, TRUE, 8, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
