INSERT INTO menu_items (id, category_id, name_en, name_kr, name_kr_subtitle, name_jp, name_vi, description_en, description_kr, description_vi, description_jp, portion_en, portion_vi, portion_kr, portion_jp, base_price, prep_time_minutes, image_url, image_public_id, alt_text, is_best_seller, is_chef_signature, is_limited, is_spicy, spice_level, spice_note, active, display_order, created_at, updated_at) VALUES ('spicy-korean-retro-katsu', 'korean', 'Spicy Korean Retro Katsu', '매운 경양식까스', NULL, '旨辛 韓国レトロとんかつ', 'Tonkatsu Kiểu Hàn Sốt Cay', 'A Korean retro-style katsu served with spicy sauce, slightly hotter than Shin Ramyun. Spice level cannot be adjusted.', '신라면보다 조금 더 매콤한 경양식 소스를 곁들인 미니 돈까스입니다. 맵기 조절은 불가합니다.', 'Tonkatsu kiểu Hàn ăn kèm sốt cay, cay hơn Shin Ramyun một chút. Không thay đổi được mức độ cay.', '韓国風ミニトンカツを辛口ソースとともにお楽しみいただけます。辛さは辛ラーメンより少し辛めです。辛さの調整はできません。', NULL, NULL, NULL, NULL, 160, 15, NULL, NULL, 'Spicy glazed Korean cutlet hotter than Shin Ramyun', false, false, false, true, 2, NULL, TRUE, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
