INSERT INTO menu_items (id, category_id, name_en, name_kr, name_kr_subtitle, name_jp, name_vi, description_en, description_kr, description_vi, description_jp, portion_en, portion_vi, portion_kr, portion_jp, base_price, prep_time_minutes, image_url, image_public_id, alt_text, is_best_seller, is_chef_signature, is_limited, is_spicy, spice_level, spice_note, active, display_order, created_at, updated_at) VALUES ('cheese-bomb-katsu', 'korean', 'Cheese Bomb Katsu', '치즈폭탄 경양까스', NULL, 'チーズ爆弾とんかつ', 'Cutlet Phô Mai Tan Chảy', 'Melted cheese inside, crispy tonkatsu outside, finished with a rich and flavorful sauce. (Regular 260k / Spicy 270k / Half & Half 270k)', '속은 치즈가 부드럽게 녹아내리고, 겉은 바삭한 돈까스에 진하고 깊은 풍미의 소스를 더했습니다. (일반 260 / 매운소스 270 / 반반 270)', 'Phô mai tan chảy bên trong, lớp vỏ tonkatsu giòn rụm, phủ sốt đậm đà. (Sốt thường 260k / Sốt cay 270k / 2 loại sốt 270k)', '中からとろけるチーズ、外はサクサクのとんかつ。濃厚でコクのあるソースとともにお楽しみください。', NULL, NULL, NULL, NULL, 260, 15, '/images/menu/korean/cheese-bomb-katsu.png', NULL, 'Melted cheese inside crispy Korean cutlet with rich sauce', false, false, false, false, 0, NULL, TRUE, 11, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
